function expenseModal(){const subs=store.categories.find(c=>c.name==='Salud')?.subs||[];return `<div class="modal-backdrop" data-close="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">Registrar un gasto</h2><p>El gasto se compartirá con las personas seleccionadas.</p></div><button class="modal-close" data-close="true" aria-label="Cerrar">×</button></header><form id="expense-form"><div class="modal-body"><div class="form-grid"><div class="form-field"><label for="expense-date">Fecha</label><input id="expense-date" name="date" type="date" value="${today.toISOString().slice(0,10)}" required></div><div class="form-field"><label for="expense-amount">Monto total (S/)</label><input id="expense-amount" name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" required></div><div class="form-field full"><label for="expense-description">¿En qué se gastó?</label><input id="expense-description" name="description" placeholder="Ej. Medicamentos para papá" required></div><div class="form-field"><label for="expense-category">Categoría</label><select id="expense-category" name="category">${store.categories.map(c=>`<option>${esc(c.name)}</option>`).join('')}</select></div><div class="form-field"><label for="expense-subcategory">Subcategoría</label><select id="expense-subcategory" name="subcategory">${subs.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="form-field"><label for="expense-beneficiary">Beneficiario</label><select id="expense-beneficiary" name="beneficiary"><option>Papá</option><option>Mamá</option><option>Vivienda</option><option>Hermano</option><option>Familia</option></select></div><div class="form-field"><label for="expense-payer">¿Quién adelantó el dinero?</label><select id="expense-payer" name="paidBy">${PEOPLE.map(p=>`<option value="${p.id}" ${p.id==='gerson'?'selected':''}>${p.first}</option>`).join('')}</select></div><fieldset class="form-field full" style="border:0;padding:0;margin:0"><legend class="form-field label" style="display:block;margin-bottom:7px">¿Quiénes comparten este gasto?</legend><div class="check-grid">${PEOPLE.map(p=>`<label class="check-option"><input type="checkbox" name="participants" value="${p.id}" checked> ${p.first}</label>`).join('')}</div></fieldset><div class="form-field"><label for="distribution">Tipo de distribución</label><select name="distribution" id="distribution"><option value="equal">En partes iguales</option><option value="custom">Personalizada</option></select></div><div class="form-field"><label for="receipt-url">Enlace del comprobante</label><input id="receipt-url" name="receipt" type="url" placeholder="https://drive.google.com/…"></div><div class="distribution-box" id="distribution-preview"><div class="distribution-line"><span>Selecciona participantes e ingresa el monto</span><strong>—</strong></div></div><div class="form-field full"><label for="expense-notes">Observaciones <span class="muted">(opcional)</span></label><textarea id="expense-notes" name="notes" placeholder="Un detalle que ayude a recordar este gasto…"></textarea></div></div></div><footer class="modal-footer"><button type="button" class="button" data-close="true">Cancelar</button><button type="submit" class="button button-primary">Guardar gasto</button></footer></form></section></div>`}
