function detailModal(id){const e=store.expenses.find(x=>x.id===id);if(!e)return'';if(role==='member'){const share=shareFor(e,memberId),paid=paidOnExpense(e,memberId),pending=Math.max(0,share-paid);return `<div class="modal-backdrop" data-close="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><p class="eyebrow">DETALLE DEL GASTO</p><h2 id="modal-title">${esc(e.description)}</h2><p>${dateLabel(e.date,{day:'2-digit',month:'long',year:'numeric'})}</p></div><button class="modal-close" data-close="true" aria-label="Cerrar">×</button></header><div class="modal-body"><section class="split-banner"><div><strong>Total gastado</strong><p>${esc(e.category)} · ${esc(e.beneficiary)}</p></div><strong class="big-number">${money(e.amount)}</strong></section><div class="personal-row"><span><strong>Tu parte</strong></span><span class="personal-amount">${money(share)}</span></div><div class="personal-row"><span><strong>Te falta aportar</strong></span><span class="personal-amount">${money(pending)}</span></div>${e.receipt?`<a class="button" href="${esc(e.receipt)}" target="_blank" rel="noreferrer" style="margin-top:12px">▧ Ver comprobante ↗</a>`:''}</div></section></div>`}return `<div class="modal-backdrop" data-close="true"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><p class="eyebrow">${esc(e.category)} · ${esc(e.beneficiary)}</p><h2 id="modal-title">${esc(e.description)}</h2><p>${dateLabel(e.date,{day:'2-digit',month:'long',year:'numeric'})} · Pagó ${person(e.paidBy).name}</p></div><button class="modal-close" data-close="true" aria-label="Cerrar">×</button></header><div class="modal-body"><section class="split-banner"><div><strong>Monto total</strong><p>${e.participants.length} participantes · ${e.distribution==='equal'?'partes iguales':'distribución personalizada'}</p></div><strong class="big-number">${money(e.amount)}</strong></section><h3 class="panel-title" style="margin:15px 0 4px">Así se distribuye</h3>${e.participants.map(id=>`<div class="personal-row"><span><strong>${person(id).name}</strong><small>${id===e.paidBy?'Adelantó el gasto · su parte se considera cubierta':'Parte asignada'}</small></span><span class="personal-amount">${money(shareFor(e,id))}<small><span class="status ${id===e.paidBy?'status-paid':'status-pending'}">${id===e.paidBy?'Cubierto':'Por aportar'}</span></small></span></div>`).join('')}<div class="category-line"><span>Observaciones</span><strong>${esc(e.notes||'Sin observaciones')}</strong></div>${e.receipt?`<a class="button" href="${esc(e.receipt)}" target="_blank" rel="noreferrer" style="margin-top:12px">▧ Ver comprobante ↗</a>`:`<p class="filter-note" style="margin-top:14px">Este gasto no tiene un comprobante enlazado.</p>`}<p class="filter-note" style="margin-top:15px">Registrado por ${person(e.paidBy).first} · El historial de cambios queda guardado.</p></div></section></div>`}
